cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance provides disaster relief, emergency assistance, and community resilience programs worldwide." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: oklch(0.56 0.2 24);
      --primary-dark: oklch(0.48 0.18 24);
      --navy: oklch(0.35 0.08 250);
      --bg: oklch(0.99 0.004 85);
      --surface: oklch(1 0 0);
      --surface-soft: oklch(0.97 0.004 85);
      --text: oklch(0.23 0.02 250);
      --muted: oklch(0.5 0.02 250);
      --border: oklch(0.9 0.01 80);
      --radius: 0.875rem;
      --shadow: 0 8px 24px oklch(0.23 0.02 250 / 0.09);
      --container: min(1120px, calc(100% - 2rem));
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text);
      background: var(--bg);
      line-height: 1.6;
    }

    .container { width: var(--container); margin-inline: auto; }
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0,0,0,0);
      border: 0;
    }

    a { color: inherit; text-decoration: none; }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: .5rem;
      border-radius: 999px;
      border: 1px solid transparent;
      min-height: 44px;
      padding: .7rem 1.2rem;
      font-weight: 600;
      transition: transform 180ms ease, background-color 180ms ease, box-shadow 180ms ease;
      cursor: pointer;
    }
    .btn:focus-visible, .icon-btn:focus-visible, .nav-link:focus-visible, .accordion-btn:focus-visible {
      outline: 3px solid oklch(0.7 0.13 250 / .4);
      outline-offset: 2px;
    }
    .btn:active { transform: scale(.97); }
    .btn-primary {
      background: var(--primary);
      color: white;
      box-shadow: 0 6px 16px oklch(0.56 0.2 24 / .25);
    }
    .btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); }
    .btn-secondary {
      background: transparent;
      border-color: var(--navy);
      color: var(--navy);
    }
    .btn-secondary:hover { background: oklch(0.95 0.03 250); }

    header {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(8px);
      background: oklch(1 0 0 / .92);
      border-bottom: 1px solid var(--border);
    }
    .utility {
      font-size: .83rem;
      border-bottom: 1px solid var(--border);
      color: var(--muted);
    }
    .utility .container {
      display: flex;
      justify-content: flex-end;
      gap: 1rem;
      padding: .45rem 0;
      flex-wrap: wrap;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: .85rem 0;
    }
    .brand { display: flex; align-items: center; gap: .7rem; }
    .logo {
      width: 2.2rem;
      height: 2.2rem;
      border-radius: 50%;
      background: radial-gradient(circle at 25% 25%, #ffffff 0%, #f8d4dc 24%, #C41E3A 58%, #9f1830 100%);
      box-shadow: inset 0 0 0 2px rgba(255,255,255,.5);
    }
    .brand strong { font-size: 1rem; letter-spacing: .01em; }

    nav ul {
      list-style: none;
      display: none;
      margin: 0;
      padding: 0;
      gap: .2rem;
      align-items: center;
    }
    .nav-link {
      display: inline-flex;
      padding: .55rem .8rem;
      border-radius: 999px;
      color: var(--navy);
      font-weight: 500;
      transition: background-color 180ms ease;
    }
    .nav-link:hover { background: oklch(0.96 0.02 250); }
    .icon-btn {
      border: 1px solid var(--border);
      background: white;
      border-radius: .7rem;
      width: 44px;
      height: 44px;
      display: inline-grid;
      place-items: center;
      cursor: pointer;
    }

    .mobile-drawer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 350ms ease;
      border-top: 1px solid var(--border);
      background: white;
    }
    .mobile-drawer.open { max-height: 420px; }
    .mobile-drawer nav ul {
      display: flex;
      flex-direction: column;
      align-items: stretch;
      padding: .8rem 0 1rem;
      gap: .3rem;
    }

    .hero {
      padding: 4rem 0 3rem;
      background: linear-gradient(145deg, oklch(0.99 0.004 85), oklch(0.96 0.012 250));
    }
    .hero-grid {
      display: grid;
      gap: 1.5rem;
      align-items: center;
    }
    h1 {
      font-size: clamp(1.95rem, 4vw, 3.25rem);
      line-height: 1.15;
      margin: 0 0 1rem;
      color: var(--navy);
    }
    .lead { font-size: clamp(1rem, 1.5vw, 1.14rem); color: oklch(0.33 0.03 250); margin: 0 0 1.5rem; }
    .hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; }

    .hero-image {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      min-height: 260px;
    }
    .hero-image img { width: 100%; height: 100%; object-fit: cover; display: block; }

    section { padding: 3.7rem 0; }
    h2 {
      margin: 0 0 .8rem;
      font-size: clamp(1.45rem, 2.2vw, 2.2rem);
      line-height: 1.2;
      color: var(--navy);
    }

    .mission p { margin: .8rem 0; color: oklch(0.3 0.02 250); }
    .mission .card {
      background: var(--surface);
      border: 1px solid var(--border);
      padding: 1.25rem;
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }

    .stats-grid {
      display: grid;
      gap: .9rem;
      grid-template-columns: repeat(2, minmax(0,1fr));
    }
    .stat-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1.1rem;
      text-align: center;
      box-shadow: var(--shadow);
    }
    .stat-value {
      display: block;
      font-size: clamp(1.6rem, 3vw, 2.4rem);
      font-weight: 800;
      color: var(--primary);
      line-height: 1.1;
      margin-bottom: .35rem;
    }

    .accordion {
      border-radius: var(--radius);
      border: 1px solid var(--border);
      overflow: hidden;
      background: white;
    }
    .accordion-item + .accordion-item { border-top: 1px solid var(--border); }
    .accordion-btn {
      width: 100%;
      text-align: left;
      background: white;
      border: 0;
      padding: 1rem;
      font-size: 1rem;
      font-weight: 600;
      color: var(--navy);
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
    }
    .accordion-btn span:last-child { transition: transform 220ms ease; }
    .accordion-btn[aria-expanded="true"] span:last-child { transform: rotate(45deg); }
    .accordion-panel {
      max-height: 0;
      overflow: hidden;
      transition: max-height 350ms ease;
      background: var(--surface-soft);
    }
    .accordion-panel p { margin: 0; padding: 0 1rem 1rem; }

    .involved-grid {
      display: grid;
      gap: 1rem;
    }
    .action-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1.2rem;
      box-shadow: var(--shadow);
    }

    .news-wrap {
      position: relative;
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 1rem;
    }
    .news-viewport { overflow: hidden; }
    .news-track {
      display: flex;
      transition: transform 320ms ease;
    }
    .news-card {
      min-width: 100%;
      padding: .5rem;
    }
    .news-card article {
      border: 1px solid var(--border);
      border-radius: .8rem;
      overflow: hidden;
      background: var(--surface-soft);
    }
    .news-card img { width: 100%; height: 170px; object-fit: cover; }
    .news-card .body { padding: .9rem; }
    .news-controls {
      display: flex;
      gap: .5rem;
      justify-content: flex-end;
      margin-top: .6rem;
    }

    .donate-cta {
      background: linear-gradient(155deg, oklch(0.37 0.08 250), oklch(0.3 0.06 250));
      color: white;
      border-radius: var(--radius);
      padding: 1.5rem;
    }

    footer {
      margin-top: 3rem;
      background: var(--navy);
      color: oklch(0.96 0.01 250);
      padding: 2.5rem 0;
    }
    .footer-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(2,minmax(0,1fr));
    }
    footer h3 { margin: 0 0 .5rem; font-size: 1rem; }
    footer ul { list-style: none; padding: 0; margin: 0; }
    footer li { margin: .4rem 0; font-size: .95rem; }
    .legal { margin-top: 1.2rem; font-size: .9rem; color: oklch(0.85 0.01 250); }

    .modal {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      background: rgba(18, 27, 39, .55);
      padding: 1rem;
      z-index: 50;
    }
    .modal.open { display: grid; }
    .modal-card {
      width: min(640px, 100%);
      background: white;
      border-radius: var(--radius);
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
      padding: 1.15rem;
      animation: modalIn 260ms ease-out;
    }
    @keyframes modalIn {
      from { transform: translateY(16px); opacity: 0; }
      to { transform: translateY(0); opacity: 1; }
    }
    .amount-grid {
      display: grid;
      gap: .6rem;
      grid-template-columns: repeat(2, minmax(0,1fr));
      margin: .75rem 0 1rem;
    }
    .amount-option {
      border: 1px solid var(--border);
      border-radius: .75rem;
      padding: .7rem;
      background: var(--surface-soft);
      cursor: pointer;
      text-align: left;
    }
    .amount-option[aria-pressed="true"] {
      border-color: var(--primary);
      background: oklch(0.96 0.04 25);
    }

    @media (min-width: 860px) {
      nav ul { display: flex; }
      .menu-btn { display: none; }
      .mobile-drawer { display: none; }
      .hero-grid { grid-template-columns: 1.2fr .9fr; }
      .stats-grid { grid-template-columns: repeat(4, minmax(0,1fr)); }
      .involved-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
      .news-card { min-width: 50%; }
      .footer-grid { grid-template-columns: repeat(4,minmax(0,1fr)); }
    }
  </style>
</head>
<body>
  <header>
    <div class="utility" aria-label="Utility links">
      <div class="container">
        <a href="#">Sign In</a>
        <a href="#">Contact Us</a>
        <a href="#">Español</a>
      </div>
    </div>
    <div class="container topbar">
      <a class="brand" href="#" aria-label="Global Aid Alliance home">
        <span class="logo" aria-hidden="true"></span>
        <strong>Global Aid Alliance</strong>
      </a>
      <nav aria-label="Main navigation">
        <ul>
          <li><a class="nav-link" href="#mission">About Us</a></li>
          <li><a class="nav-link" href="#programs">Disaster Relief</a></li>
          <li><a class="nav-link" href="#programs">Programs &amp; Services</a></li>
          <li><a class="nav-link" href="#involved">Volunteer</a></li>
          <li><a class="nav-link" href="#footer">Find Local Chapter</a></li>
          <li><button class="btn btn-primary" data-open-donate>Donate</button></li>
        </ul>
      </nav>
      <button class="icon-btn menu-btn" aria-label="Open menu" aria-controls="mobile-menu" aria-expanded="false" id="menuToggle">
        ☰
      </button>
    </div>
    <div id="mobile-menu" class="mobile-drawer" aria-hidden="true">
      <div class="container">
        <nav aria-label="Mobile navigation">
          <ul>
            <li><a class="nav-link" href="#mission">About Us</a></li>
            <li><a class="nav-link" href="#programs">Disaster Relief</a></li>
            <li><a class="nav-link" href="#programs">Programs &amp; Services</a></li>
            <li><a class="nav-link" href="#involved">Volunteer</a></li>
            <li><a class="nav-link" href="#footer">Find Local Chapter</a></li>
            <li><button class="btn btn-primary" data-open-donate>Donate</button></li>
          </ul>
        </nav>
      </div>
    </div>
  </header>

  <main>
    <section class="hero" id="top">
      <div class="container hero-grid">
        <div>
          <h1>When Disaster Strikes, We're There</h1>
          <p class="lead">From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" data-open-donate>Donate Now</button>
            <a class="btn btn-secondary" href="#involved">Become a Volunteer</a>
          </div>
        </div>
        <div class="hero-image">
          <img src="https://images.unsplash.com/photo-1526976668912-1a811878dd37?auto=format&fit=crop&w=900&q=80" alt="Relief volunteers supporting families after a storm in a diverse community" loading="lazy">
        </div>
      </div>
    </section>

    <section class="mission" id="mission">
      <div class="container">
        <h2>Our Mission</h2>
        <div class="card">
          <p><strong>Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.</strong></p>
          <p>We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most — regardless of race, religion, nationality, or political affiliation.</p>
          <p>From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.</p>
        </div>
      </div>
    </section>

    <section class="impact" id="impact">
      <div class="container">
        <h2>Impact at a Glance</h2>
        <p>These figures represent real lives changed — families sheltered after storms, blood delivered to hospitals, and communities rebuilt stronger than before.</p>
        <div class="stats-grid" aria-label="Impact statistics">
          <article class="stat-card"><span class="stat-value" data-target="12000000">0</span><strong>people assisted annually</strong></article>
          <article class="stat-card"><span class="stat-value" data-target="50000">0</span><strong>volunteers active</strong></article>
          <article class="stat-card"><span class="stat-value" data-target="190">0</span><strong>countries reached</strong></article>
          <article class="stat-card"><span class="stat-value" data-target="850000000">0</span><strong>raised last fiscal year</strong></article>
        </div>
      </div>
    </section>

    <section id="programs">
      <div class="container">
        <h2>Programs &amp; Services</h2>
        <div class="accordion" id="programAccordion">
          <div class="accordion-item">
            <button class="accordion-btn" aria-expanded="false">Disaster Relief <span>＋</span></button>
            <div class="accordion-panel"><p>Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.</p></div>
          </div>
          <div class="accordion-item">
            <button class="accordion-btn" aria-expanded="false">Blood Donation <span>＋</span></button>
            <div class="accordion-panel"><p>Operating one of the largest blood collection networks, we supply approximately 40% of the nation's blood and blood products to hospitals and medical facilities.</p></div>
          </div>
          <div class="accordion-item">
            <button class="accordion-btn" aria-expanded="false">Emergency Preparedness <span>＋</span></button>
            <div class="accordion-panel"><p>Training individuals, families, and organizations through workshops, certification courses, and community drills to prepare for and respond to emergencies.</p></div>
          </div>
          <div class="accordion-item">
            <button class="accordion-btn" aria-expanded="false">International Humanitarian Aid <span>＋</span></button>
            <div class="accordion-panel"><p>Partnering with a global network of humanitarian organizations to deliver relief and recovery programs in conflict zones and disaster-affected regions worldwide.</p></div>
          </div>
          <div class="accordion-item">
            <button class="accordion-btn" aria-expanded="false">Community Health <span>＋</span></button>
            <div class="accordion-panel"><p>Providing health and safety education, disease prevention programs, and support services to underserved communities, including mental health resources for disaster survivors.</p></div>
          </div>
        </div>
      </div>
    </section>

    <section id="involved">
      <div class="container">
        <h2>Get Involved</h2>
        <div class="involved-grid">
          <article class="action-card">
            <h3>Volunteer With Us</h3>
            <p>Join over 50,000 volunteers who give their time and skills to help people in need.</p>
            <a href="#" class="btn btn-secondary">Find Volunteer Opportunities</a>
          </article>
          <article class="action-card">
            <h3>Start a Fundraiser</h3>
            <p>Rally your community, workplace, or school to raise funds for disaster relief.</p>
            <a href="#" class="btn btn-secondary">Start Your Fundraiser</a>
          </article>
          <article class="action-card">
            <h3>Give Blood</h3>
            <p>Every two seconds, someone in the country needs blood. Help save lives.</p>
            <a href="#" class="btn btn-secondary">Find a Blood Drive</a>
          </article>
        </div>
      </div>
    </section>

    <section id="news">
      <div class="container">
        <h2>Latest News</h2>
        <div class="news-wrap">
          <div class="news-viewport">
            <div class="news-track" id="newsTrack">
              <div class="news-card"><article><img src="https://images.unsplash.com/photo-1469571486292-b53601010376?auto=format&fit=crop&w=900&q=80" alt="Relief teams setting up temporary shelters after a hurricane"><div class="body"><h3>Hurricane Response Update</h3><p>Teams are providing shelter and supplies to over 15,000 families displaced by Hurricane Marlena across 12 counties.</p></div></article></div>
              <div class="news-card"><article><img src="https://images.unsplash.com/photo-1473773508845-188df298d2d1?auto=format&fit=crop&w=900&q=80" alt="Volunteers distributing supplies during wildfire evacuations"><div class="body"><h3>Wildfire Relief Efforts</h3><p>Emergency shelters have opened in three western states as volunteers distribute meals, water, and comfort kits.</p></div></article></div>
              <div class="news-card"><article><img src="https://images.unsplash.com/photo-1584515933487-779824d29309?auto=format&fit=crop&w=900&q=80" alt="Community blood donation center with donors and medical staff"><div class="body"><h3>Blood Drive Campaign</h3><p>Our summer campaign has collected over 120,000 units so far, with new donation sites added nationwide.</p></div></article></div>
              <div class="news-card"><article><img src="https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=900&q=80" alt="Volunteer portrait in front of emergency response supplies"><div class="body"><h3>Volunteer Spotlight</h3><p>Meet Daniela Torres, a disaster response volunteer deployed to seven emergencies in three years.</p></div></article></div>
            </div>
          </div>
          <div class="news-controls">
            <button class="icon-btn" id="newsPrev" aria-label="Previous news">←</button>
            <button class="icon-btn" id="newsNext" aria-label="Next news">→</button>
          </div>
        </div>
      </div>
    </section>

    <section class="container">
      <div class="donate-cta">
        <h2>Your Gift Makes a Difference</h2>
        <p>A donation of any size helps us respond to disasters, train volunteers, and support communities in crisis. <strong>91 cents of every dollar goes directly to humanitarian services.</strong></p>
        <button class="btn btn-primary" data-open-donate>Donate Now</button>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container">
      <div class="footer-grid">
        <div><h3>Programs</h3><ul><li>Disaster Relief</li><li>Blood Donation</li><li>Emergency Preparedness</li><li>International Aid</li><li>Community Health</li></ul></div>
        <div><h3>Get Involved</h3><ul><li>Volunteer</li><li>Donate</li><li>Start a Fundraiser</li><li>Corporate Partnerships</li></ul></div>
        <div><h3>About</h3><ul><li>Our Mission</li><li>Leadership</li><li>Financials</li><li>Careers</li><li>Press Room</li></ul></div>
        <div><h3>Support</h3><ul><li>Contact Us</li><li>FAQs</li><li>Find Local Chapter</li><li>Privacy Policy</li><li>Terms of Service</li></ul></div>
      </div>
      <p class="legal">© 2024 Global Aid Alliance. All rights reserved. A 501(c)(3) nonprofit organization. Tax ID: 53-0196742 · Facebook · X (Twitter) · Instagram · LinkedIn · YouTube</p>
    </div>
  </footer>

  <div class="modal" id="donateModal" role="dialog" aria-modal="true" aria-labelledby="donateTitle">
    <div class="modal-card">
      <div style="display:flex;justify-content:space-between;gap:1rem;align-items:center;">
        <h2 id="donateTitle" style="margin:0;">Donate Now</h2>
        <button class="icon-btn" id="closeDonate" aria-label="Close donation modal">✕</button>
      </div>
      <p>Select an amount to power urgent relief and long-term recovery.</p>
      <div class="amount-grid" id="amountGrid">
        <button class="amount-option" data-amount="$25" aria-pressed="false">$25 <small>5 emergency blankets</small></button>
        <button class="amount-option" data-amount="$50" aria-pressed="false">$50 <small>Food + water for one week</small></button>
        <button class="amount-option" data-amount="$100" aria-pressed="false">$100 <small>Emergency shelter materials</small></button>
        <button class="amount-option" data-amount="$250" aria-pressed="false">$250 <small>Volunteer response training</small></button>
      </div>
      <label for="customAmount"><strong>Custom Amount</strong></label>
      <input id="customAmount" type="number" min="1" placeholder="Enter amount" style="width:100%;margin:.4rem 0 1rem;padding:.7rem;border:1px solid var(--border);border-radius:.65rem;" />
      <button class="btn btn-primary" style="width:100%;" id="confirmDonate">Complete Donation</button>
    </div>
  </div>

  <script>
    const menuToggle = document.getElementById('menuToggle');
    const mobileMenu = document.getElementById('mobile-menu');
    menuToggle?.addEventListener('click', () => {
      const open = mobileMenu.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(open));
      mobileMenu.setAttribute('aria-hidden', String(!open));
    });

    const donateModal = document.getElementById('donateModal');
    const openDonateButtons = document.querySelectorAll('[data-open-donate]');
    const closeDonate = document.getElementById('closeDonate');
    const customAmount = document.getElementById('customAmount');
    const amountOptions = document.querySelectorAll('.amount-option');

    const openModal = () => {
      donateModal.classList.add('open');
      document.body.style.overflow = 'hidden';
    };
    const closeModal = () => {
      donateModal.classList.remove('open');
      document.body.style.overflow = '';
    };
    openDonateButtons.forEach(btn => btn.addEventListener('click', openModal));
    closeDonate?.addEventListener('click', closeModal);
    donateModal?.addEventListener('click', (e) => { if (e.target === donateModal) closeModal(); });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && donateModal.classList.contains('open')) closeModal();
    });

    amountOptions.forEach(option => {
      option.addEventListener('click', () => {
        amountOptions.forEach(o => o.setAttribute('aria-pressed', 'false'));
        option.setAttribute('aria-pressed', 'true');
        customAmount.value = option.dataset.amount.replace(/[^0-9]/g, '');
      });
    });

