    const targets = [12000000, 50000, 190, 850000000];
    const prefixes = ['', '', '', '$'];
    const suffixes = ['', '', '', ''];

    const runCounters = () => {
      statEls.forEach((el, idx) => {
        const target = targets[idx];
        const duration = 1200;
        const start = performance.now();
        const step = (now) => {
          const progress = Math.min((now - start) / duration, 1);
          const current = Math.floor(target * (1 - Math.pow(1 - progress, 3)));
          el.textContent = prefixes[idx] + formatStat(current) + suffixes[idx];
          if (progress < 1) requestAnimationFrame(step);
          else {
            if (idx === 0) el.textContent = '12M';
            if (idx === 1) el.textContent = '50K';
            if (idx === 2) el.textContent = '190';
            if (idx === 3) el.textContent = '$850M';
          }
        };
        requestAnimationFrame(step);
      });
    };

    const impactSection = document.getElementById('impact');
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          runCounters();
          observer.disconnect();
        }
      });
    }, { threshold: 0.35 });
    observer.observe(impactSection);

    updateCarousel();
  </script>
