  <div class="modal" id="donateModal" role="dialog" aria-modal="true" aria-labelledby="donateTitle">
    <div class="modal-card">
      <div style="display:flex;justify-content:space-between;gap:1rem;align-items:center;">
        <h2 id="donateTitle" style="margin:0;">Donate Now</h2>
        <button class="icon-btn" id="closeDonate" aria-label="Close donation modal">✕</button>
      </div>
      <p>Select an amount to power urgent relief and long-term recovery.</p>
      <div class="amount-grid" id="amountGrid">
        <button class="amount-option" data-amount="$25" aria-pressed="false">$25 <small>5 emergency blankets</small></button>
        <button class="amount-option" data-amount="$50" aria-pressed="false">$50 <small>Food + water for one week</small></button>
