  <script>
    const menuToggle = document.getElementById('menuToggle');
    const mobileMenu = document.getElementById('mobile-menu');
    menuToggle?.addEventListener('click', () => {
      const open = mobileMenu.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(open));
      mobileMenu.setAttribute('aria-hidden', String(!open));
    });

    const donateModal = document.getElementById('donateModal');
    const openDonateButtons = document.querySelectorAll('[data-open-donate]');
    const closeDonate = document.getElementById('closeDonate');
    const customAmount = document.getElementById('customAmount');
    const amountOptions = document.querySelectorAll('.amount-option');

    const openModal = () => {
      donateModal.classList.add('open');
      document.body.style.overflow = 'hidden';
    };
    const closeModal = () => {
      donateModal.classList.remove('open');
      document.body.style.overflow = '';
    };
    openDonateButtons.forEach(btn => btn.addEventListener('click', openModal));
    closeDonate?.addEventListener('click', closeModal);
    donateModal?.addEventListener('click', (e) => { if (e.target === donateModal) closeModal(); });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && donateModal.classList.contains('open')) closeModal();
    });

    amountOptions.forEach(option => {
      option.addEventListener('click', () => {
        amountOptions.forEach(o => o.setAttribute('aria-pressed', 'false'));
        option.setAttribute('aria-pressed', 'true');
        customAmount.value = option.dataset.amount.replace(/[^0-9]/g, '');
      });
    });

    const accordions = document.querySelectorAll('.accordion-item');
    accordions.forEach(item => {
      const button = item.querySelector('.accordion-btn');
      const panel = item.querySelector('.accordion-panel');
      button.addEventListener('click', () => {
        const isOpen = button.getAttribute('aria-expanded') === 'true';
        button.setAttribute('aria-expanded', String(!isOpen));
        panel.style.maxHeight = isOpen ? '0px' : panel.scrollHeight + 'px';
      });
    });

    const newsTrack = document.getElementById('newsTrack');
    const newsPrev = document.getElementById('newsPrev');
    const newsNext = document.getElementById('newsNext');
    const slides = newsTrack.children.length;
    let currentIndex = 0;

    const visibleCount = () => window.innerWidth >= 860 ? 2 : 1;
    const maxIndex = () => Math.max(0, slides - visibleCount());
    const updateCarousel = () => {
      const width = 100 / visibleCount();
      newsTrack.style.transform = `translateX(-${currentIndex * width}%)`;
    };

    newsNext.addEventListener('click', () => {
      currentIndex = currentIndex >= maxIndex() ? 0 : currentIndex + 1;
      updateCarousel();
    });
    newsPrev.addEventListener('click', () => {
      currentIndex = currentIndex <= 0 ? maxIndex() : currentIndex - 1;
      updateCarousel();
    });
    window.addEventListener('resize', () => {
      currentIndex = Math.min(currentIndex, maxIndex());
      updateCarousel();
    });

    const formatStat = (value) => {
      if (value >= 1000000) return (value / 1000000).toFixed(value % 1000000 === 0 ? 0 : 1) + 'M';
      if (value >= 1000) return (value / 1000).toFixed(value % 1000 === 0 ? 0 : 1) + 'K';
      return value.toString();
    };

    const statEls = document.querySelectorAll('.stat-value');
    const targets = [12000000, 50000, 190, 850000000];
    const prefixes = ['', '', '', '$'];
    const suffixes = ['', '', '', ''];

    const runCounters = () => {
      statEls.forEach((el, idx) => {
        const target = targets[idx];
        const duration = 1200;
        const start = performance.now();
        const step = (now) => {
          const progress = Math.min((now - start) / duration, 1);
          const current = Math.floor(target * (1 - Math.pow(1 - progress, 3)));
          el.textContent = prefixes[idx] + formatStat(current) + suffixes[idx];
          if (progress < 1) requestAnimationFrame(step);
          else {
            if (idx === 0) el.textContent = '12M';
            if (idx === 1) el.textContent = '50K';
            if (idx === 2) el.textContent = '190';
            if (idx === 3) el.textContent = '$850M';
          }
        };
        requestAnimationFrame(step);
      });
    };

    const impactSection = document.getElementById('impact');
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          runCounters();
          observer.disconnect();
        }
      });
    }, { threshold: 0.35 });
    observer.observe(impactSection);

    updateCarousel();
  </script>
</body>
</html>
